// Which calculator type a GYG menu item is.
function gygType(name){
  const n = name;
  if (/^Little G's/.test(n)) return /Bowl/.test(n) ? 'littleGsBowl' : /Nachos/.test(n) ? 'littleGsNachos' : /Burrito/.test(n) ? 'littleGsBurrito' : null;
  if (/^Big Brekkie Burrito/.test(n)) return 'bigBrekkieBurrito';
  if (/^Brekkie Burrito/.test(n)) return 'breakfastBurrito';
  if (/^Brekkie Bowl/.test(n)) return 'brekkieBowl';
  if (/^Brekkie Quesadilla Plus/.test(n)) return 'brekkieQuesadillaPlus';
  if (/^Brekkie Quesadilla/.test(n)) return 'brekkieQuesadilla';
  if (/^Brekkie Taco/.test(n)) return 'breakfastTaco';
  if (/^Toast/.test(n)) return 'toast';
  if (/^\$3 Taco/.test(n)) return 'threeDollarTaco';
  if (/Tender Taco/.test(n)) return 'chickenTenderTaco';
  if (/Crispy Chicken Tenders/.test(n) && !/Caesar/.test(n)) return 'crispyChickenTenders';
  const t = /Caesar Cali Burrito/.test(n) ? 'caesarCaliBurrito' : /Caesar Burrito/.test(n) ? 'caesarBurrito' : /Caesar Salad/.test(n) ? 'caesarSalad'
    : /Cali Burrito/.test(n) ? 'caliBurrito' : /Nacho Fries/.test(n) ? 'nachoFries' : /Nachos/.test(n) ? 'nachos' : /Enchilada/.test(n) ? 'enchiladas'
    : /Bowl/.test(n) ? 'bowl' : /Burrito/.test(n) ? 'burrito' : /Quesadilla Plus/.test(n) ? 'quesadillasPlus' : /Quesadilla/.test(n) ? 'quesadillas'
    : /(Soft|Hard) Taco/.test(n) ? 'regularTaco' : /Queso Fries/.test(n) ? 'quesoFries' : /Salad/.test(n) ? 'salads' : null;
  if (!t || !/\bMini\b/.test(n)) return t;
  return {bowl:'miniBowl', burrito:'miniBurrito', caliBurrito:'miniCaliBurrito', enchiladas:'miniEnchilada', nachoFries:'miniNachoFries', nachos:'miniNachos',
    salads:'miniSalad', caesarSalad:'miniCaesarSalad', caesarBurrito:'miniCaesarBurrito', caesarCaliBurrito:'miniCaesarCaliBurrito'}[t] || null;
}
const tidyNut = o => { const n = Object.fromEntries(Object.entries(o).filter(([, v]) => v != null)); return Object.keys(n).length ? n : undefined; };
// Every change a menu item allows: [{key, id, kind, name, kj, p, c, f, nut, price}]. kind: f = extra filling, a = extra, s = swap, r = take off.
// Swaps and take-offs carry their own negative amounts, so every change is simply added on.
function modsFor(base){
  if (!base) return [];
  const g = base.chain === 'gyg' && GYG_MODS.t[gygType(base.name)];
  if (g) return ['f','a','s','r'].flatMap(k => (g[k] || []).map(i => {
    const [id, name, kj, p, c, f, sat, sugar, fibre, sodium] = GYG_MODS.o[i];
    return {key:`gyg:${k}:${id}`, id, kind:k, name, kj, p, c, f, nut:tidyNut({sat, sugar, fibre, sodium})};
  }));
  // Elsewhere: that place's own add-ons that are sold with this kind of item (Subway's extra meat, GYG's dipping sauces).
  return BUILTIN.filter(x => x.chain === base.chain && x.cat === 'extra' && extraFits(base, x))
    .map(x => ({key:'item:' + x.id, id:x.id, kind:'a', name:x.name, kj:x.kj, p:x.p, c:x.c, f:x.f, nut:x.nut, price:x.price}));
}

function extraFits(m, x){
  if (x.name.startsWith('Mini Extra:')) return /\bMini\b/.test(m.name);
  if (x.name.startsWith('Brekkie Extra:')) return m.cat === 'breakfast';
  if (x.name.startsWith('Dipping Sauce:')) return /Tender|Fries|Nugget|Wing|Pops|Fried Chicken|Chicken Piece|Pieces? of Chicken|Fillet Piece|Popcorn|Boneless|Strips|Bolas|Bites|Chips|Onion Rings|Mozzarella Sticks|Drumstick/i.test(m.name);
  if (x.chain === 'gyg' && x.name.startsWith('Extra ')) return m.cat !== 'breakfast' && !/\bMini\b|Little G|Taco|Quesadilla|Fries|Tender/.test(m.name);
  if (x.chain === 'sub' && x.name.startsWith('Extra ')) return !/Nachos/.test(m.name);
  if (x.chain === 'grilld') return /Chips|Tenders|Bites|Onion Rings|Pocket Rocket/.test(m.name);
  if (x.chain === 'nandos') return /Chips|Tenders|Drums/.test(m.name);
  return true;
}
